Certainly! Below is an example of how you might implement a Contextual Multi-Armed Bandit (CMAB) algorithm using Object-Oriented Programming (OOP) principles in Python. This implementation will use three different models to make decisions based on the context.

```python
import numpy as np

class Model:
    def __init__(self):
        pass

    def predict(self, context):
        raise NotImplementedError("Subclasses must implement this method")

class LinearModel(Model):
    def __init__(self):
        super().__init__()
        self.weights = None

    def fit(self, contexts, rewards):
        # Simple linear regression with least squares
        X = np.hstack((np.ones((len(contexts), 1)), contexts))
        self.weights = np.linalg.inv(X.T @ X) @ X.T @ rewards

    def predict(self, context):
        if self.weights is None:
            return 0
        x = np.array([1] + list(context))
        return x @ self.weights

class RandomModel(Model):
    def predict(self, context):
        return np.random.rand()

class EpsilonGreedyBandit:
    def __init__(self, models, epsilon=0.1):
        self.models = models
        self.epsilon = epsilon
        self.rewards = {model: [] for model in models}
        self.contexts = []

    def select_action(self, context):
        if np.random.rand() < self.epsilon:
            action = np.random.choice(len(self.models))
        else:
            predictions = [model.predict(context) for model in self.models]
            action = np.argmax(predictions)

        reward = np.random.normal(loc=predictions[action], scale=0.1)
        self.rewards[self.models[action]].append(reward)
        self.contexts.append(context)

        return action

    def update_models(self):
        for model, rewards in self.rewards.items():
            if len(rewards) > 0:
                model.fit(np.array(self.contexts), np.array(rewards))

# Example usage
if __name__ == "__main__":
    num_contexts = 1000
    dim_context = 5
    contexts = np.random.rand(num_contexts, dim_context)

    linear_model = LinearModel()
    random_model = RandomModel()
    models = [linear_model, random_model]

    bandit = EpsilonGreedyBandit(models, epsilon=0.1)

    for _ in range(num_contexts):
        action = bandit.select_action(contexts[_])
        print(f"Selected action: {action}")

    bandit.update_models()
```

### Explanation:

1. **Model Class**: A base class that defines the interface for all models.
2. **LinearModel Class**: Implements a simple linear regression model.
3. **RandomModel Class**: Returns a random prediction.
4. **EpsilonGreedyBandit Class**: Manages the selection of actions and updating of models.
   - `select_action`: Chooses an action either randomly or greedily based on the current estimates.
   - `update_models`: Updates the weights of the linear model after collecting enough data.

This code provides a basic framework for implementing a CMAB algorithm with multiple models. You can extend it by adding more sophisticated models or modifying the reward function according to your specific problem requirements.

