```csharp
using System;
using System.IO;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;

public class WordMerger
{
    public static void MergeDocuments(string sourceDocPath1, string sourceDocPath2, string outputDocPath)
    {
        // Load the first document
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(sourceDocPath1, false))
        {
            MainDocumentPart mainPart1 = doc1.MainDocumentPart;
            Body body1 = mainPart1.Document.Body;

            // Create a new document for merging
            using (WordprocessingDocument mergedDoc = WordprocessingDocument.Create(outputDocPath, WordprocessingDocumentType.Document))
            {
                MainDocumentPart mainPartMerged = mergedDoc.AddMainDocumentPart();
                mainPartMerged.Document = new Document(new Body());

                // Copy headers and footers from the first document
                foreach (var section in mainPart1.Document.Sections)
                {
                    SectionProperties sectionProps = section.SectionProperties;
                    HeaderReference headerRef = section.HeaderReference;
                    FooterReference footerRef = section.FooterReference;

                    if (headerRef != null && !string.IsNullOrEmpty(headerRef.Id.Value))
                    {
                        HeaderPart headerPart = mainPart1.GetPartsOfType<HeaderPart>().FirstOrDefault(h => h.HeaderId == headerRef.Id);
                        if (headerPart != null)
                        {
                            HeaderPart newHeaderPart = mainPartMerged.AddNewPart<HeaderPart>();
                            newHeaderPart.HeaderId = headerRef.Id;
                            newHeaderPart.Header = headerPart.Header.CloneNode(true);
                        }
                    }

                    if (footerRef != null && !string.IsNullOrEmpty(footerRef.Id.Value))
                    {
                        FooterPart footerPart = mainPart1.GetPartsOfType<FooterPart>().FirstOrDefault(f => f.FooterId == footerRef.Id);
                        if (footerPart != null)
                        {
                            FooterPart newFooterPart = mainPartMerged.AddNewPart<FooterPart>();
                            newFooterPart.FooterId = footerRef.Id;
                            newFooterPart.Footer = footerPart.Footer.CloneNode(true);
                        }
                    }

                    // Add the first two pages of content
                    int count = 0;
                    foreach (Paragraph paragraph in body1.Elements<Paragraph>())
                    {
                        if (count >= 2) break;
                        Paragraph newParagraph = paragraph.CloneNode(true);
                        mainPartMerged.Document.Body.AppendChild(newParagraph);
                        count++;
                    }
                }

                // Copy styles from the first document
                StylesPart stylesPart1 = mainPart1.DocumentStylesPart;
                if (stylesPart1 != null)
                {
                    StylesPart stylesPartMerged = mainPartMerged.AddNewPart<StylesPart>();
                    stylesPartMerged.Styles = stylesPart1.Styles.CloneNode(true);
                }

                // Load the second document
                using (WordprocessingDocument doc2 = WordprocessingDocument.Open(sourceDocPath2, false))
                {
                    MainDocumentPart mainPart2 = doc2.MainDocumentPart;
                    Body body2 = mainPart2.Document.Body;

                    // Append the rest of the content from the second document
                    foreach (Paragraph paragraph in body2.Elements<Paragraph>())
                    {
                        Paragraph newParagraph = paragraph.CloneNode(true);
                        mainPartMerged.Document.Body.AppendChild(newParagraph);
                    }

                    // Copy glossary entries from the second document
                    GlossaryDocumentPart glossaryPart2 = mainPart2.GlossaryDocumentPart;
                    if (glossaryPart2 != null)
                    {
                        GlossaryDocumentPart glossaryPartMerged = mainPartMerged.AddNewPart<GlossaryDocumentPart>();
                        glossaryPartMerged.GlossaryDocument = glossaryPart2.GlossaryDocument.CloneNode(true);
                    }
                }
            }
        }
    }
}
```

### Explanation:
- The function `MergeDocuments` takes three parameters: paths to the source documents (`sourceDocPath1`, `sourceDocPath2`) and the path where the merged document will be saved (`outputDocPath`).
- It opens both input documents and creates a new merged document.
- Headers and footers from the first document are copied over.
