import hashlib
import json

class Block:
    def __init__(self, index, previous_hash, timestamp, data, hash):
        self.index = index
        self.previous_hash = previous_hash
        self.timestamp = timestamp
        self.data = data
        self.hash = hash

class Blockchain:
    def __init__(self):
        self.chain = [self.create_genesis_block()]
        self.nodes = {}

    def create_genesis_block(self):
        return Block(0, "0", "1/1/2023", {}, self.calculate_hash(0, "0", "1/1/2023", {}))

    def calculate_hash(self, index, previous_hash, timestamp, data):
        value = str(index) + str(previous_hash) + str(timestamp) + str(data)
        return hashlib.sha256(value.encode('utf-8')).hexdigest()

    def add_node(self, node_id, initial_deposit):
        if node_id not in self.nodes:
            self.nodes[node_id] = {
                'deposit': initial_deposit,
                'data': {},
                'fees': 0
            }

    def store_data(self, node_id, data, size, lifetime):
        if node_id in self.nodes:
            deposit = size * lifetime
            self.nodes[node_id]['deposit'] += deposit
            self.nodes[node_id]['data'][hashlib.sha256(json.dumps(data).encode('utf-8')).hexdigest()] = {
                'size': size,
                'lifetime': lifetime,
                'reward_per_node': deposit / len(self.nodes),
                'remaining_lifetime': lifetime
            }
            new_block = Block(len(self.chain), self.chain[-1].hash, "now", {'node_id': node_id, 'data': data}, self.calculate_hash(len(self.chain), self.chain[-1].hash, "now", {'node_id': node_id, 'data': data}))
            self.chain.append(new_block)

