        if node_id in self.nodes and data_hash in self.nodes[node_id]['data']:
            self.nodes[node_id]['fees'] += 1
            return True
        return False

    def delete_data(self, node_id, data_hash):
        if node_id in self.nodes and data_hash in self.nodes[node_id]['data']:
            del self.nodes[node_id]['data'][data_hash]
            return True
        return False

