import java.util.List;
import java.util.Optional;

public class ListChecker {

    public static <T> T getSingleEntryOrThrow(List<T> list) {
        // Check if the list is empty or contains more than one element
        long count = list.stream().count();

        if (count == 0) {
            return null; // Return null if the list is empty
        } else if (count > 1) {
            throw new IllegalStateException("List contains more than one entry");
        }

        // If there's exactly one entry, return it wrapped in Optional
        return list.get(0);
    }

    public static void main(String[] args) {
        List<String> singleEntryList = List.of("single");
        List<String> multipleEntriesList = List.of("one", "two");
        List<String> emptyList = List.of();

        try {
            System.out.println(getSingleEntryOrThrow(singleEntryList)); // Should print: single
            System.out.println(getSingleEntryOrThrow(multipleEntriesList)); // Should throw an exception
        } catch (IllegalStateException e) {
            System.err.println(e.getMessage());
        }

        System.out.println(getSingleEntryOrThrow(emptyList)); // Should print: null
    }
}
```

