Here is an implementation of your requirements:

**FavoritesManager Class**

```php
<?php

namespace App\Favorites;

use App\Models\User;
use App\Models\Favorite;

class FavoritesManager
{
    /**
     * Add a favorite name for a given user.
     *
     * @param User $user The authenticated user (or null if not logged in)
     * @param string $name The name to add to the favorites list
     */
    public function addFavorite(User $user = null, string $name): void
    {
        // If there's no user, assume it's a guest and save to session
        if (!$user) {
            session()->push('favorites', $name);
        } else {
            // Save to database
            Favorite::updateOrCreate([
                'user_id' => $user->id,
                'name' => $name,
            ]);
        }
    }

    /**
     * Remove a favorite name from the list.
     *
     * @param User $user The authenticated user (or null if not logged in)
     * @param string $name The name to remove from the favorites list
     */
    public function removeFavorite(User $user = null, string $name): void
    {
        // If there's no user, assume it's a guest and remove from session
        if (!$user) {
            session()->forget("favorites.*", fn ($key) => str_contains($key, $name));
        } else {
            // Delete from database
            Favorite::where('user_id', $user->id)->where('name', $name)->delete();
        }
    }

    /**
     * Get all favorite names for a given user.
     *
     * @param User|null $user The authenticated user (or null if not logged in)
     * @return array An array of favorite names
     */
    public function getFavorites(User $user = null): array
    {
        // If there's no user, return session data
        if (!$user) {
            return session('favorites') ?? [];
        }

        // Return database data
        return Favorite::where('user_id', $user->id)->pluck('name')->toArray();
    }
}
