       expect(require('your-module').default()).toBe('custom default mock');
       expect(require('your-module').someFunction()).toBe('custom someFunction mock');
     });
   });
   ```

3. **Alternative Approach Using `jest.resetModules()`:**

   Another approach is to reset the modules between tests so that they start fresh without any previous mocks applied.

   ```javascript
