Here's a simple implementation:

```typescript
interface TcpHeader {
  sourcePort: number;
  destinationPort: number;
  sequenceNumber: number;
  acknowledgmentNumber: number;
  dataOffset: number; // The size of the TCP header in 32-bit words (4 bytes)
  reserved: number;
  flags: {
    fin: boolean;
    syn: boolean;
    rst: boolean;
    psh: boolean;
    ack: boolean;
    urg: boolean;
    ece: boolean;
    cwr: boolean;
  };
  windowSize: number;
  checksum: number;
  urgentPointer: number;
}

function parseTcpHeader(data: Uint8Array): TcpHeader {
  const tcpHeader = new DataView(data.buffer, data.byteOffset);

  const sourcePort = tcpHeader.getUint16(0);
  const destinationPort = tcpHeader.getUint16(2);
  const sequenceNumber = tcpHeader.getUint32(4);
  const acknowledgmentNumber = tcpHeader.getUint32(8);

  const dataOffset = (tcpHeader.getUint8(12) >> 4) * 4;

  const reserved = tcpHeader.getUint8(12) & 0x0F;
  const flags = {
    fin: !!(tcpHeader.getUint8(13) & 0x01),
    syn: !!(tcpHeader.getUint8(13) & 0x02),
    rst: !!(tcpHeader.getUint8(13) & 0x04),
    psh: !!(tcpHeader.getUint8(13) & 0x08),
    ack: !!(tcpHeader.getUint8(13) & 0x10),
    urg: !!(tcpHeader.getUint8(13) & 0x20),
    ece: !!(tcpHeader.getUint8(13) & 0x40),
    cwr: !!(tcpHeader.getUint8(13) & 0x80),
  };

  const windowSize = tcpHeader.getUint16(14);
  const checksum = tcpHeader.getUint16(16);
  const urgentPointer = tcpHeader.getUint16(18);

  return {
    sourcePort,
    destinationPort,
    sequenceNumber,
    acknowledgmentNumber,
    dataOffset,
    reserved,
    flags,
    windowSize,
    checksum,
    urgentPointer,
  };
}

// Example usage:
const buffer = new Uint8Array([
  0x50, 0x54, // Source port
  0x0A, 0x0B, // Destination port
  0x00, 0x00, 0x00, 0x01, // Sequence number
  0x00, 0x00, 0x00, 0x02, // Acknowledgment number
  0x50, 0x00, 0x00, 0x00, // Data offset, reserved, flags, window size
  0x00, 0x00, // Checksum
  0x00, 0x00, // Urgent pointer
]);

const parsedHeader = parseTcpHeader(buffer);
console.log(parsedHeader);
```

