To generate a stream of prime numbers in Rust, you can use the Sieve of Eratosthenes algorithm or implement a simple trial division method. Below is an example using a generator function that yields prime numbers one by one:

```rust
use std::io;

fn main() {
    let mut primes = PrimeStream::new();
    println!("First 10 prime numbers:");
    for _ in 0..10 {
        if let Some(prime) = primes.next() {
            println!("{}", prime);
        }
    }
}

struct PrimeStream {
    current: u64,
    is_prime: bool,
}

impl PrimeStream {
    fn new() -> Self {
        PrimeStream {
            current: 2,
            is_prime: true,
        }
    }
}

impl Iterator for PrimeStream {
    type Item = u64;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            if self.is_prime {
                return Some(self.current);
            }

            self.current += 1;
            self.is_prime = self.is_prime_number(self.current);

            if self.is_prime {
                break;
            }
        }
    }

    fn is_prime_number(&self, n: u64) -> bool {
        if n <= 1 {
            return false;
        }
        if n == 2 {
            return true;
        }
        if n % 2 == 0 {
            return false;
        }

        let sqrt_n = (n as f64).sqrt() as u64 + 1;
        for i in (3..sqrt_n).step_by(2) {
            if n % i == 0 {
                return false;
            }
        }
        true
    }
}
```

