Now, let's create the `spriteEditor.js` file:

```javascript
const canvas = document.getElementById('editor');
const ctx = canvas.getContext('2d');

// Define a simple Sprite class
class Sprite {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.color = 'red'; // Default color for now
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

let sprites = [];

function drawSprites() {
    ctx.clearRect(0, 0, canvas.width, canvas.height); // Clear the canvas before redrawing

    sprites.forEach(sprite => {
        sprite.draw();
    });
}

// Add event listener for mouse clicks to add new sprites
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const mouseX = event.clientX - rect.left;
    const mouseY = event.clientY - rect.top;

    // Create a new sprite at the clicked position
    const newSprite = new Sprite(mouseX, mouseY, 50, 50);
    sprites.push(newSprite);

