#include <iostream>
#include <vector>
#include <algorithm>
#include <random>

// Function to perform Fisher-Yates shuffle on a given vector
void fisherYatesShuffle(std::vector<int>& vec) {
    // Seed the random number generator
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<> dis(0, vec.size() - 1);

    // Perform the shuffle
    for (size_t i = vec.size(); i > 1; --i) {
        size_t j = dis(gen) % i;
        std::swap(vec[i - 1], vec[j]);
    }
}

