Here's a JavaScript function that takes a JSON object, an entity key, and returns an array of objects containing the found values and their corresponding paths:

```javascript
function findEntity(jsonObj, entityKey) {
    const results = [];

    function traverse(obj, path = []) {
        if (typeof obj === 'object' && obj !== null) {
            Object.entries(obj).forEach(([key, value]) => {
                const newPath = [...path, key];
                if (key === entityKey) {
                    results.push({ value: value, path: newPath });
                }
                traverse(value, newPath);
            });
        }
    }

    traverse(jsonObj);

    return results;
}

