### src/main.rs

```rust
use std::fs;
use std::process::Command;
use regex::Regex;

fn main() {
    // Path to the input file containing URLs
    let file_path = "urls.txt";

    // Read all lines from the file into a vector of strings
    match fs::read_to_string(file_path) {
        Ok(content) => {
            let lines: Vec<&str> = content.lines().collect();

            // Regular expression to match YouTube URLs
            let re = Regex::new(r"^https?://(?:www\.)?(?:youtube\.com/watch|youtu\.be)/.*$").unwrap();

            // Filter out only YouTube URLs
            let youtube_urls: Vec<String> = lines.iter()
                .filter(|line| re.is_match(line))
                .map(|line| line.to_string())
                .collect();

            // Download each YouTube URL using yt-dlp
            for url in youtube_urls {
                println!("Downloading: {}", url);
                Command::new("yt-dlp")
                    .arg(url)
                    .output()
                    .expect("Failed to execute command");
            }
        },
        Err(e) => eprintln!("Error reading file {}: {}", file_path, e),
    }
}
```

