using System.Net.Http;
using System.Security.Cryptography.X509Certificates;
using System.Text;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        // Path to your client certificate file (e.g., .pfx or .cer)
        string certPath = "path/to/your/certificate.pfx";
        // Password for the certificate if it's encrypted
        string certPassword = "your_certificate_password";

        // Create an X509Certificate2 object from the certificate file
        X509Certificate2 clientCert = new X509Certificate2(certPath, certPassword);

        // URL of the server you want to send the POST request to
        string url = "https://example.com/api/resource";

        // Data to be sent in the POST request body
        string postData = "{\"key\":\"value\"}";

        // Send the POST request with the client certificate
        using (HttpClientHandler handler = new HttpClientHandler())
        {
            // Set the client certificate to be used for authentication
            handler.ClientCertificates.Add(clientCert);

            using (HttpClient client = new HttpClient(handler))
            {
                try
                {
                    // Send the POST request asynchronously
                    HttpResponseMessage response = await client.PostAsync(url, new StringContent(postData, Encoding.UTF8, "application/json"));

                    // Ensure the request was successful
                    response.EnsureSuccessStatusCode();

                    // Read the response content as a string
                    string responseBody = await response.Content.ReadAsStringAsync();

                    // Output the response
