void NetworkTrafficDecoderService::OnStart() {
    WSADATA wsaData;
    WSAStartup(MAKEWORD(2, 2), &wsaData);

    // Open adapter handle
    m_adapterHandle = NPF_OpenAdapter("Your Adapter Name");
    if (!m_adapterHandle) {
        // Handle error
        return;
    }

    // Start capturing packets
    NPF_StartCapture(m_adapterHandle);

    while (true) {
        NPFPACKETHEADER header;
        BYTE* buffer;

        int result = NPF_ReadPacket(m_adapterHandle, &header, &buffer);
        if (result == ERROR_SUCCESS) {
            // Process packet here...
        } else {
            // Handle error
        }
    }
}

void NetworkTrafficDecoderService::OnStop() {
    if (m_adapterHandle) {
        NPF_StopCapture(m_adapterHandle);
        NPF_CloseAdapter(m_adapterHandle);
    }

    WSACleanup();
}

